import re
import datetime
from pypdf import PdfReader
from typing import Dict, Any, List

class ITTSalaryParser:
    """
    Specialized parser for ITT ITALIA S.r.l. Salary Slips.
    """

    @staticmethod
    def parse(file_path: str) -> Dict[str, Any]:
        reader = PdfReader(file_path)
        text = ""
        for page in reader.pages:
            text += page.extract_text()

        # Regex patterns for key fields
        patterns = {
            "employer": r"ITT ITALIA S\.r\.l\.",
            "employee_name": r"Sig\.\s+([A-Z\s]+)\s+\d{4}",
            "net_income": r"Netto in busta\s+([\d\.,]+)",
            "total_earnings": r"Tot\.Comp\.\s+([\d\.,]+)",
            "total_deductions": r"Tot\.Trat\.\s+([\d\.,]+)",
            "month_ref": r"([A-Za-z]+\s+\d{4})\s+Pagina\s+1"
        }

        extracted = {
            "employer": "ITT ITALIA S.r.l.",
            "employee_name": "Unknown",
            "net_income": 0.0,
            "total_earnings": 0.0,
            "total_deductions": 0.0,
            "month_reference": "Unknown",
            "date": datetime.date.today(),
            "items": [],
            "leaves": []
        }

        # Helper to convert Italian format 1.234,56 to float
        def to_float(val: str) -> float:
            if not val: return 0.0
            return float(val.replace(".", "").replace(",", "."))

        # Basic extraction
        for key, pattern in patterns.items():
            match = re.search(pattern, text)
            if match:
                if key == "month_ref": extracted["month_reference"] = match.group(1)
                elif key == "employee_name": extracted["employee_name"] = match.group(1).strip()
                elif key in ["net_income", "total_earnings", "total_deductions"]:
                    extracted[key] = to_float(match.group(1))

        # Parsing Table Items (Earnings/Deductions)
        # Sample row: 0001 Ore Ordinarie X X 80,00 13,7363 1.098,90
        item_pattern = r"(\d{4})\s+([A-Za-z\s/&]+)\s+(?:X\s+X)?\s*([\d\.,]*)\s+([\d\.,]*)\s+([\d\.,]+)"
        for match in re.finditer(item_pattern, text):
            extracted["items"].append({
                "code": match.group(1),
                "description": match.group(2).strip(),
                "base_data": to_float(match.group(4)) if match.group(4) else 0.0,
                "earnings": to_float(match.group(5)),
                "deductions": 0.0 # Logic to distinguish would go here
            })

        # Parsing Leave Stats
        # Simple extraction for Ferie, BancaOr, ROL
        # Patterns based on the bottom grid
        leave_types = ["Ferie", "BancaOr", "ExFes/Rol"]
        for lt in leave_types:
            # This is a simplification; a more precise table parser would be used in production
            extracted["leaves"].append({
                "leave_type": lt,
                "accrued": 0.0, 
                "used": 0.0,
                "remaining": 0.0
            })

        return extracted

